import time
import asyncio
from fastapi import FastAPI

app = FastAPI()

# 1. async def: Chạy trực tiếp trên Event Loop chính
# BẮT BUỘC dùng non-blocking await. Tốc độ cực cao, chịu tải hàng vạn kết nối đồng thời.
@app.get("/async-correct")
async def async_route():
    await asyncio.sleep(1) # Non-blocking sleep: Nhường CPU cho request khác
    return {"type": "non-blocking async"}

# 2. def thường: FastAPI tự động offload sang Threadpool của AnyIO
# An toàn cho các tác vụ đồng bộ, blocking mà không làm đơ Event Loop chính.
@app.get("/sync-safe")
def sync_route():
    time.sleep(1) # Blocking sleep: Được cách ly trong worker thread riêng!
    return {"type": "safe threadpool offload"}

