from typing import Optional

# Cú pháp chuẩn hiện đại của Pydantic v2 trong FastAPI
class UserProfileSchema(BaseModel):
    # Cấu hình model thông qua model_config dictionary hoặc ConfigDict
    model_config = ConfigDict(
        from_attributes=True,   # Thay thế cho orm_mode = True ở v1
        str_strip_whitespace=True # Tự động strip khoảng trắng đầu cuối
    )

    username: str
    email: str
    age: Optional[int] = None

    # Thay thế cho @validator cũ của v1
