    @classmethod
    def validate_username(cls, v: str) -> str:
        if len(v) < 3:
            raise ValueError("Username must have at least 3 characters")
        return v.lower()

    # Thay thế cho @root_validator cũ của v1
    @model_validator(mode="after")
    def check_business_rules(self) -> "UserProfileSchema":
        if self.age is not None and self.age < 18 and "admin" in self.username:
            raise ValueError("Minors cannot have admin username")
        return self

# Sử dụng serialization mới:
# data_dict = schema.model_dump(exclude_unset=True) # Thay cho schema.dict(...)
