from pydantic import BaseModel, Field
from typing import Optional

app = FastAPI()

# Schema dành riêng cho Partial Update (Mọi field đều optional)
class UserPatchRequest(BaseModel):
    full_name: Optional[str] = Field(default=None, min_length=2)
    bio: Optional[str] = Field(default=None, max_length=500)
    phone_number: Optional[str] = None

# Entity giả lập trong DB
class UserDbModel:
    def __init__(self, id: int, full_name: str, bio: str, phone: str):
        self.id = id
        self.full_name = full_name
        self.bio = bio
        self.phone_number = phone

fake_db = {1: UserDbModel(1, "Nam Nguyen", "Senior Engineer", "0901234567")}

@app.patch("/api/v1/users/{user_id}")
async def patch_user(user_id: int, payload: UserPatchRequest):
    user = fake_db.get(user_id)
    if not user:
        raise HTTPException(status_code=404, detail="User not found")

    # 1. TRỌNG TÂM: Chỉ lấy các field client CỐ Ý truyền lên
    update_data = payload.model_dump(exclude_unset=True)

    if not update_data:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="No fields provided for update"
        )

    # 2. Cập nhật động các thuộc tính trên ORM model
    for field, value in update_data.items():
        setattr(user, field, value)

    # await db.commit()
    return {
        "status": "updated",
        "updated_fields": list(update_data.keys()),
        "user": {
            "id": user.id,
            "full_name": user.full_name,
            "bio": user.bio,
            "phone_number": user.phone_number
        }
    }

