from fastapi import FastAPI, Request, status
from fastapi.responses import JSONResponse
from fastapi.exceptions import RequestValidationError
from pydantic import BaseModel, Field

app = FastAPI()

# 1. Custom Domain Exception (Không phụ thuộc vào Web Framework)
class InsufficientFundsException(Exception):
    def __init__(self, current_balance: float, required_amount: float):
        self.current_balance = current_balance
        self.required_amount = required_amount

# 2. Đăng ký Global Exception Handler cho Business Exception
@app.exception_handler(InsufficientFundsException)
async def insufficient_funds_handler(request: Request, exc: InsufficientFundsException):
    return JSONResponse(
        status_code=status.HTTP_400_BAD_REQUEST,
        content={
            "type": "https://api.example.com/errors/insufficient-funds",
            "title": "Business Rule Violation",
            "status": 400,
            "detail": f"Required {exc.required_amount} but balance is only {exc.current_balance}",
            "instance": str(request.url)
        }
    )

# 3. Ghi đè Handler mặc định của Pydantic RequestValidationError
@app.exception_handler(RequestValidationError)
async def validation_exception_handler(request: Request, exc: RequestValidationError):
    simplified_errors = []
    for err in exc.errors():
        field = " -> ".join([str(loc) for loc in err["loc"] if loc != "body"])
        simplified_errors.append({"field": field, "message": err["msg"]})

    return JSONResponse(
        status_code=status.HTTP_422_UNPROCESSABLE_ENTITY,
        content={
            "title": "Validation Failed",
            "status": 422,
            "errors": simplified_errors
        }
    )

