from datetime import datetime, timedelta, timezone
from typing import Annotated
from fastapi import FastAPI, Depends, HTTPException, status
from fastapi.security import OAuth2PasswordBearer, OAuth2PasswordRequestForm
import jwt
from pydantic import BaseModel

app = FastAPI()

SECRET_KEY = "super-secret-key-change-in-production"
ALGORITHM = "HS256"
ACCESS_TOKEN_EXPIRE_MINUTES = 30

# 1. Khởi tạo OAuth2 Scheme liên kết tới endpoint cấp token (Hiển thị form login trên Swagger)
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="/api/v1/auth/token")

class TokenResponse(BaseModel):
    access_token: str
    token_type: str

class UserPayload(BaseModel):
    user_id: int
    username: str

# 2. Endpoint Đăng nhập: Cấp Access Token
@app.post("/api/v1/auth/token", response_model=TokenResponse)
async def login_for_access_token(form_data: Annotated[OAuth2PasswordRequestForm, Depends()]):
    # Xác thực mật khẩu (Ví dụ: Passlib verify)
    if form_data.username != "namnguyen" or form_data.password != "password123":
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Incorrect username or password",
            headers={"WWW-Authenticate": "Bearer"}
        )

    expire = datetime.now(timezone.utc) + timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES)
    to_encode = {"sub": form_data.username, "user_id": 1, "exp": expire}
    encoded_jwt = jwt.encode(to_encode, SECRET_KEY, algorithm=ALGORITHM)

    return {"access_token": encoded_jwt, "token_type": "bearer"}

# 3. Dependency giải mã và xác thực User từ Token
async def get_current_user(token: Annotated[str, Depends(oauth2_scheme)]) -> UserPayload:
    credentials_exception = HTTPException(
        status_code=status.HTTP_401_UNAUTHORIZED,
        detail="Could not validate credentials",
        headers={"WWW-Authenticate": "Bearer"}
    )
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        username: str = payload.get("sub")
        user_id: int = payload.get("user_id")
        if username is None:
            raise credentials_exception
        return UserPayload(user_id=user_id, username=username)
    except jwt.PyJWTError:
        raise credentials_exception

# 4. Bảo vệ Endpoint bằng Dependency
@app.get("/api/v1/users/me")
async def read_users_me(current_user: Annotated[UserPayload, Depends(get_current_user)]):
    return {"message": f"Welcome back, {current_user.username}!", "user_id": current_user.user_id}

